begin;
create temporary table commercial_fixtures(kind text primary key,id uuid default gen_random_uuid());
insert into commercial_fixtures(kind) values('admin'),('person'),('outside'),('director'),('store'),('otherstore');
grant select on commercial_fixtures to authenticated;
insert into auth.users(id,email) select id,id||'@example.invalid' from commercial_fixtures where kind in ('admin','person','outside','director');
insert into public.eo_profiles(id,display_name,role) select id,'Teste comercial',case when kind='admin' then 'admin' when kind='director' then 'diretor' else 'gerente' end from commercial_fixtures where kind in ('admin','person','outside','director');
insert into public.eo_stores(id,code,name,region) select id,left(id::text,20),'Loja teste comercial',kind from commercial_fixtures where kind in ('store','otherstore');
insert into public.eo_store_members(user_id,store_id) select p.id,s.id from commercial_fixtures p cross join commercial_fixtures s where (p.kind in ('person','director') and s.kind='store') or (p.kind='outside' and s.kind='otherstore');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from commercial_fixtures where kind='person'),true);
do $$ declare sid uuid:=(select id from commercial_fixtures where kind='store'); otherstore uuid:=(select id from commercial_fixtures where kind='otherstore'); req uuid:=gen_random_uuid(); product uuid; scan uuid; result jsonb; denied boolean; begin
 if has_table_privilege(current_user,'public.eo_product_requests','SELECT') or has_table_privilege(current_user,'public.eo_assortment_scans','UPDATE') then raise exception 'FAIL: acesso direto'; end if;
 product:=public.eo_save_product_request(sid,'Falta blusa branca masculina 44','{"category":"Vestuário","product":"Blusa","color":"Branca","gender":"Masculino","size":"44","demand":"Alta"}',req);
 if public.eo_save_product_request(sid,'Falta blusa branca masculina 44','{"category":"Vestuário","product":"Blusa","color":"Branca","gender":"Masculino","size":"44","demand":"Alta"}',req)<>product then raise exception 'FAIL: duplicidade pedido'; end if;
 denied:=false;begin perform public.eo_save_product_request(otherstore,'Produto fora','{}',gen_random_uuid());exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'FAIL: outra loja';end if;
 scan:=public.eo_begin_assortment(sid,'4006381333931',gen_random_uuid());
 result:=public.eo_commercial_page('assortment',current_date-1,current_date+1,sid);if result->>'total'<>'1' or result->'items'->0->'payload'->>'status'<>'draft' then raise exception 'FAIL: leitura não preservada'; end if;
 perform public.eo_save_assortment(scan,'{"PP":0,"EXG":2,"34":1,"44":3,"54":0}');
 result:=public.eo_commercial_page('assortment',current_date-1,current_date+1,sid);if result->'items'->0->'payload'->>'status'<>'completed' then raise exception 'FAIL: contagem não concluída'; end if;
 denied:=false;begin perform public.eo_save_assortment(scan,'{"33":1}');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: tamanho inválido';end if;
 denied:=false;begin perform public.eo_save_assortment(scan,'{"PP":-1}');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: quantidade negativa';end if;
 denied:=false;begin perform public.eo_save_product_request(sid,'Relato áudio','{}',gen_random_uuid(),auth.uid()||'/teste.m4a',12,null);exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: áudio sem revisão';end if;
 perform set_config('request.jwt.claim.sub',(select id::text from commercial_fixtures where kind='outside'),true);
 result:=public.eo_commercial_page('product',current_date-1,current_date+1,sid);if result->>'total'<>'0' then raise exception 'FAIL: vazamento';end if;
 denied:=false;begin perform public.eo_save_assortment(scan,'{"PP":3}');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'FAIL: editar outra pessoa';end if;
 perform set_config('request.jwt.claim.sub',(select id::text from commercial_fixtures where kind='director'),true);
 result:=public.eo_commercial_page('product',current_date-1,current_date+1,sid);if result->>'total'<>'1' then raise exception 'FAIL: diretor não vê abrangência';end if;
 perform set_config('request.jwt.claim.sub',(select id::text from commercial_fixtures where kind='admin'),true);
 result:=public.eo_commercial_page('product',current_date-1,current_date+1,sid);if result->>'total'<>'1' then raise exception 'FAIL: admin não vê consolidado';end if;
end;$$;
reset role;
rollback;
select 'PASSOU: pedidos, sortimento, tamanhos, quantidades, revisão e escopo real' as resultado;
